// The editor's tabs (v3 Task 12 split of js/app.js): Looks, Adjust, Lens, Crop, Frames, Text.
// ---------- Tabs ----------
// ↓ imports (generated by the v3 split; edit freely)
import { updateButtons } from '../collage-host.js';
import { syncControls } from '../engine-host.js';
import { setHistoryHooks } from '../history.js';
import { cropUi, syncCrop } from './crop.js';
import { syncText } from './text.js';
import { applyParts, applyToPhotos, otherSelected } from '../photos.js';
import { scheduleRender } from '../preview.js';
import { photoChanged } from '../session/recovery.js';
import { $, app, elements, state } from '../state.js';
// ↑ imports
function setTab(tabButton) {
  document.querySelectorAll('.control-tabs [role=tab]').forEach(tab => {
    const selected = tab === tabButton;
    tab.setAttribute('aria-selected', selected);
    tab.tabIndex = selected ? 0 : -1;
    $(`#${tab.getAttribute('aria-controls')}`).hidden = !selected;
  });
  if (tabButton.id === 'cropTab' && document.body.dataset.tab !== 'crop') cropUi.previousTab = `${document.body.dataset.tab || 'looks'}Tab`;
  document.body.dataset.tab = tabButton.id.replace('Tab', '');
  // Crop: the whole photo with the crop box replaces the preview while the tab is open.
  elements.cropStage.hidden = tabButton.id !== 'cropTab' || !state.image;
  if (!elements.cropStage.hidden) { cropUi.key = ''; syncCrop(); }
  syncText(); // the selection box shows only in the Text tab
}

// History calls back into the editor through these (js/history.js sits below the panels and the preview).
setHistoryHooks({ syncControls, scheduleRender, afterCommit() { updateButtons(); photoChanged(app.activeId); if (app.liveEdit) applyToPhotos(otherSelected(), applyParts); } });

// ↓ shared with other editor modules (generated by the v3 split)
export { setTab };
